// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"IB Physics Theme A covers motion: how things move and why. It's the foundation for everything else.","blocks":[{"t":"key","text":"Kinematics (SUVAT for constant acceleration): v = u + at, s = ut + ½at², v² = u² + 2as, s = ½(u + v)t. Projectiles: horizontal and vertical motion are independent."},{"t":"p","text":"Newton's laws: F = ma (more generally F = Δp/Δt). Momentum p = mv is conserved in isolated systems. Impulse = FΔt = Δp."},{"t":"p","text":"Circular motion: centripetal acceleration a = v²/r = ω²r toward the center."},{"t":"ex","problem":"A car accelerates from 10 m/s to 25 m/s in 5 s. Find its acceleration and displacement.","steps":["a = (25 − 10)/5 = 3 m/s²"],"answer":"s = ½(10 + 25)(5) = 87.5 m"},{"t":"lab","kind":"lab","title":"Ball rolling off a table","aim":"Roll a ball off a bench at different speeds and measure where it lands.","sets":[{"name":"v","start":2,"label":"Launch speed (m/s)","min":0.5,"max":6,"step":0.1},{"name":"h","start":1,"label":"Bench height (m)","min":0.5,"max":2,"step":0.1}],"outs":[{"name":"t","expr":"sqrt(2*h/g)","label":"Time in the air (s)"},{"name":"x","expr":"v*t","label":"Horizontal distance (m)"}],"steps":["Record the landing distance for 5 launch speeds at a fixed height.","Change the height. Does the time in the air depend on the speed?"],"noise":3,"result":"Horizontal and vertical motion are independent. The time in the air depends only on the height (t = √(2h/g)), so the landing distance is directly proportional to launch speed.","plot":{"x":"v","y":"x"}}]},{"say":"Energy is conserved, but it changes form. And at very high speeds, Einstein's relativity takes over.","blocks":[{"t":"key","text":"Work W = Fs cos θ. Kinetic energy Eₖ = ½mv² = p²/2m. Gravitational potential energy ΔEₚ = mgΔh. Elastic potential energy Eₕ = ½kx². Power P = W/t = Fv. Efficiency = useful output/input."},{"t":"p","text":"Energy is conserved in isolated systems; friction transfers energy to thermal energy."},{"t":"p","text":"HL adds rigid body mechanics (torque, moment of inertia, angular momentum) and special relativity: time dilation, length contraction and the invariance of the speed of light."},{"t":"ex","problem":"A 60 kg runner climbs 10 m of stairs in 12 s. Find her power output.","steps":["ΔEₚ = 60 × 9.8 × 10 = 5,880 J"],"answer":"P = 5,880/12 = 490 W"}]}],[{"say":"Theme B explains matter in terms of particles: heat, temperature, gases and even Earth's climate.","blocks":[{"t":"key","text":"Temperature measures average kinetic energy of particles. Specific heat capacity: Q = mcΔT. Specific latent heat (phase changes): Q = mL."},{"t":"p","text":"Heat transfer: conduction, convection and radiation. A black body emits radiation with power P = σAT⁴ (Stefan–Boltzmann law); Wien's law: λₘₐₓT = 2.9 × 10⁻³ m K."},{"t":"p","text":"The greenhouse effect: Earth absorbs short-wavelength solar radiation and emits infrared; greenhouse gases absorb and re-emit infrared, warming the surface. Albedo is the fraction of radiation reflected."},{"t":"p","text":"Ideal gas law: pV = nRT. Kinetic theory links pressure to particle collisions."},{"t":"lab","kind":"lab","title":"Specific heat capacity of a metal block","aim":"Heat a 1 kg metal block with a 50 W immersion heater and record its temperature.","sets":[{"name":"t","start":120,"label":"Time (s)","min":0,"max":600,"step":10},{"name":"c","start":900,"label":"Specific heat capacity (J/kg·K)","min":380,"max":2000,"step":10}],"outs":[{"name":"T","expr":"20 + 50*t/(1*c)","label":"Temperature (°C)"}],"steps":["Record the temperature every 100 s for aluminum (900 J/kg·K).","Switch to copper (385) and compare the slope."],"noise":2,"result":"The temperature rises linearly; the slope equals P/(mc), so c = P/(m × slope). Real results come out a little high because some heat escapes to the surroundings, so the block is insulated.","plot":{"x":"t","y":"T"}}]},{"say":"Electric circuits are also part of Theme B, since current is the flow of charged particles.","blocks":[{"t":"key","text":"Current I = ΔQ/Δt. Potential difference V = W/q. Resistance R = V/I; resistivity R = ρL/A. Power P = IV = I²R = V²/R."},{"t":"p","text":"Series circuits: same current, voltages add, R = R₁ + R₂. Parallel circuits: same voltage, currents add, 1/R = 1/R₁ + 1/R₂."},{"t":"p","text":"Cells have emf ε and internal resistance r: ε = I(R + r). Ohmic conductors follow V ∝ I at constant temperature; filament lamps and diodes are non-ohmic."},{"t":"ex","problem":"A 12 V battery with internal resistance 1 Ω drives a 5 Ω resistor. Find the current.","steps":["I = ε/(R + r) = 12/6"],"answer":"2 A"}]}],[{"say":"Theme C covers oscillations and waves, from pendulums to sound and light.","blocks":[{"t":"key","text":"Simple harmonic motion: acceleration is proportional to displacement and opposite in direction: a = −ω²x. Period of a pendulum T = 2π√(l/g); mass on a spring T = 2π√(m/k)."},{"t":"p","text":"Waves transfer energy without transferring matter. v = fλ. Transverse waves oscillate perpendicular to travel; longitudinal waves oscillate parallel (sound)."},{"t":"p","text":"Electromagnetic waves travel at c = 3.00 × 10⁸ m/s in a vacuum and can be polarized (transverse only)."},{"t":"ex","problem":"A wave has frequency 500 Hz and wavelength 0.68 m. Find its speed.","steps":["v = fλ = 500 × 0.68"],"answer":"340 m/s"}]},{"say":"Waves reflect, refract, diffract and interfere. These behaviors explain rainbows, echoes and radar.","blocks":[{"t":"key","text":"Snell's law: n₁ sin θ₁ = n₂ sin θ₂. Total internal reflection occurs above the critical angle. Diffraction is greatest when the gap is similar to the wavelength."},{"t":"p","text":"Interference: constructive when path difference = nλ; destructive when path difference = (n + ½)λ. Double-slit fringe spacing s = λD/d."},{"t":"p","text":"Standing waves form from two waves traveling in opposite directions, creating nodes and antinodes. On a string, λ = 2L/n."},{"t":"p","text":"Doppler effect: a moving source or observer changes the observed frequency; approaching raises it, receding lowers it. It's used in radar speed guns and to measure redshift of galaxies."},{"t":"lab","kind":"lab","title":"Doppler effect with a moving speaker","aim":"Move a speaker playing a steady note toward or away from a microphone and measure the frequency received.","sets":[{"name":"vs","start":30,"label":"Source speed (m/s, + toward you)","min":-100,"max":100,"step":5},{"name":"f","start":440,"label":"Emitted frequency (Hz)","min":200,"max":1000,"step":10}],"outs":[{"name":"fo","expr":"f*343/(343 - vs)","label":"Observed frequency (Hz)"}],"steps":["Record the observed frequency for sources approaching and receding."],"noise":0.5,"result":"An approaching source compresses the waves (higher pitch); a receding source stretches them (lower pitch): f′ = f·v/(v − vₛ). The same effect shifts light from distant galaxies to the red, showing the universe is expanding.","plot":{"x":"vs","y":"fo"}}]}],[{"say":"Theme D describes forces that act at a distance through fields: gravity, electricity and magnetism.","blocks":[{"t":"key","text":"Newton's law of gravitation: F = GMm/r². Gravitational field strength g = GM/r². Orbital speed v = √(GM/r). Kepler's third law: T² ∝ r³."},{"t":"p","text":"Coulomb's law: F = kq₁q₂/r². Electric field strength E = F/q; between parallel plates E = V/d."},{"t":"p","text":"Field lines show direction and strength (closer lines = stronger field)."},{"t":"p","text":"HL adds gravitational and electric potential and potential energy, escape velocity and equipotentials."},{"t":"ex","problem":"If the distance between two masses triples, how does the gravitational force change?","steps":["F ∝ 1/r²"],"answer":"It becomes 1/9 as strong"},{"t":"lab","kind":"lab","title":"Satellite orbits","aim":"Place a satellite at different distances from Earth's center and calculate its orbital period and speed.","sets":[{"name":"r","start":7,"label":"Orbit radius (thousand km)","min":6.6,"max":45,"step":0.1}],"outs":[{"name":"T","expr":"2*pi*sqrt((r*1e6)^3/(6.674e-11*5.97e24))/3600","label":"Period (hours)"},{"name":"v","expr":"sqrt(6.674e-11*5.97e24/(r*1e6))/1000","label":"Orbital speed (km/s)"}],"steps":["Record the period at 5 radii, including the International Space Station (6.8).","Find the radius where the period is 24 hours."],"noise":0.5,"result":"T² ∝ r³ (Kepler's third law). The ISS circles in about 90 minutes; at 42,200 km the period is 24 hours, a geostationary orbit that stays above one point on Earth.","plot":{"x":"r","y":"T"}}]},{"say":"Moving charges create magnetic fields and feel magnetic forces. Changing fields induce currents.","blocks":[{"t":"key","text":"Force on a moving charge: F = qvB sin θ. Force on a current-carrying wire: F = BIL sin θ. Charged particles in uniform magnetic fields move in circles: r = mv/(qB)."},{"t":"p","text":"Magnetic fields around wires and solenoids follow the right-hand grip rule."},{"t":"p","text":"HL: electromagnetic induction. Magnetic flux Φ = BA cos θ. Faraday's law: ε = −N ΔΦ/Δt. Lenz's law: the induced current opposes the change that caused it. Generators and transformers rely on induction."},{"t":"ex","problem":"A proton moves at 2 × 10⁶ m/s perpendicular to a 0.5 T field. Is the force on it doing work?","steps":["The magnetic force is perpendicular to velocity"],"answer":"No; it changes direction but not speed"}]}],[{"say":"Theme E explores the atom and nucleus, where classical physics breaks down.","blocks":[{"t":"key","text":"Atomic spectra show discrete energy levels: a photon's energy E = hf equals the difference between levels. The photoelectric effect (HL) shows light's particle nature: Eₖmax = hf − Φ."},{"t":"p","text":"Radioactive decay is random and spontaneous. Alpha (helium nucleus), beta-minus (electron and antineutrino), beta-plus (positron and neutrino) and gamma (photon) decay. Half-life is the time for half the nuclei to decay. Activity A = λN."},{"t":"ex","problem":"A sample has a half-life of 3 days. What fraction remains after 9 days?","steps":["9 days = 3 half-lives"],"answer":"(1/2)³ = 1/8"},{"t":"lab","kind":"lab","title":"Gamma rays and distance","aim":"Move a Geiger counter away from a gamma source and measure the count rate.","sets":[{"name":"d","start":10,"label":"Distance (cm)","min":5,"max":50,"step":1},{"name":"A","start":20000,"label":"Source strength","min":5000,"max":50000,"step":1000}],"outs":[{"name":"C","expr":"A/d^2 + 20","label":"Count rate (counts/min, including 20 background)"}],"steps":["First measure the background count (about 20 per minute).","Record the count rate at 5 distances and subtract the background."],"noise":5,"result":"Gamma intensity follows an inverse-square law: doubling the distance cuts the corrected count rate to a quarter. Distance is one of the best protections from radiation.","plot":{"x":"d","y":"C"}}]},{"say":"Nuclear reactions power reactors and stars by converting mass into energy.","blocks":[{"t":"key","text":"E = mc². The mass defect (difference between the mass of separate nucleons and the nucleus) equals the binding energy divided by c². Binding energy per nucleon peaks near iron-56, so fission of heavy nuclei and fusion of light nuclei both release energy."},{"t":"p","text":"Fission: a neutron splits uranium-235 into smaller nuclei and more neutrons, allowing a chain reaction. Reactors use moderators (slow neutrons), control rods (absorb neutrons) and coolant."},{"t":"p","text":"Fusion powers stars. A star's life cycle depends on its mass; the Hertzsprung–Russell diagram plots luminosity against temperature."}]}]];
export default text;
